def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = grid[0][0]
    seen = [[False] * w for _ in range(h)]
    comps = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg or seen[r][c]:
                continue
            seen[r][c] = True
            stack = [(r, c)]
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy, xx = y+dy, x+dx
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] != bg and not seen[yy][xx]:
                        seen[yy][xx] = True
                        stack.append((yy, xx))
            comps.append(cells)
    edges = []
    for i in range(len(comps)):
        for j in range(i+1, len(comps)):
            best = min((abs(r1-r2)+abs(c1-c2),r1,c1,r2,c2)
                       for r1,c1 in comps[i] for r2,c2 in comps[j])
            edges.append((best[0],i,j,best[1:]))
    parent = list(range(len(comps)))
    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]
    chosen = []
    for d,i,j,coords in sorted(edges):
        a,b = find(i),find(j)
        if a != b:
            parent[b] = a
            chosen.append((i,j,coords))
    tree_pairs = {(i,j) for i,j,_ in chosen}
    diagonal = [(d,i,j,coords) for d,i,j,coords in edges
                if coords[0] != coords[2] and coords[1] != coords[3] and (i,j) not in tree_pairs]
    if diagonal:
        d,i,j,coords = min(diagonal)
        chosen.append((i,j,coords))
    out = [row[:] for row in grid]
    for i,j,(r1,c1,r2,c2) in chosen:
        # Horizontal first, then vertical, forming a shortest L bridge.
        dx = 1 if c2 >= c1 else -1
        for c in range(c1+dx,c2+dx,dx):
            if grid[r1][c] == bg:
                out[r1][c] = 2
        dy = 1 if r2 >= r1 else -1
        for r in range(r1+dy,r2+dy,dy):
            if grid[r][c2] == bg:
                out[r][c2] = 2
    return out

